package com.shopsphere.repository; import com.shopsphere.entity.Product; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; public interface ProductRepository extends JpaRepository<Product,UUID>{Optional<Product> findBySlug(String slug); @Query("select p from Product p where p.active=true and (:q is null or lower(p.name) like lower(concat('%',:q,'%'))) and (:categoryId is null or p.category.id=:categoryId)") Page<Product> search(@Param("q") String q,@Param("categoryId") UUID categoryId,Pageable pageable);}